import torch
from torch.utils.data import Dataset, DataLoader
import numpy as np
from sklearn.preprocessing import StandardScaler

class TabularDataset(Dataset):
    def __init__(self, X: np.ndarray, y: np.ndarray, scaler=None, fit_scaler=False):
        if scaler is None:
            scaler = StandardScaler()
        if fit_scaler:
            X = scaler.fit_transform(X)
        else:
            X = scaler.transform(X)
        self.X      = torch.FloatTensor(X)
        self.y      = torch.LongTensor(y)
        self.scaler = scaler

    def __len__(self) -> int:
        return len(self.X)

    def __getitem__(self, idx: int):
        return self.X[idx], self.y[idx]

# Usage
from sklearn.datasets import make_classification
X, y = make_classification(n_samples=5000, n_features=20, random_state=42)

train_ds = TabularDataset(X[:4000], y[:4000], fit_scaler=True)
val_ds   = TabularDataset(X[4000:], y[4000:], scaler=train_ds.scaler)

train_loader = DataLoader(train_ds, batch_size=256, shuffle=True,
                          num_workers=0, pin_memory=False)
val_loader   = DataLoader(val_ds,   batch_size=512, shuffle=False)

for X_batch, y_batch in train_loader:
    print(f'Batch shape: {X_batch.shape}, dtype: {X_batch.dtype}')
    break

import torch
import torch.nn as nn

class SimpleNet(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.fc = nn.Linear(dim, dim)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return torch.relu(self.fc(x))

model = SimpleNet(64)
model.eval()

# Method 1: torch.jit.trace — records operations on a sample input
sample = torch.randn(1, 64)
traced = torch.jit.trace(model, sample)
traced.save('model_traced.pt')  # portable serialized model
print('Traced output:', traced(sample).shape)

# Method 2: torch.jit.script — analyzes Python AST, supports control flow
@torch.jit.script
def conditional_op(x: torch.Tensor, flag: bool) -> torch.Tensor:
    if flag:  # control flow preserved in scripted IR
        return torch.relu(x)
    else:
        return torch.sigmoid(x)

print('Script with flag=True: ', conditional_op(torch.randn(3), True))
print('Script with flag=False:', conditional_op(torch.randn(3), False))

# Load and run traced model in a new session (no model definition needed)
loaded = torch.jit.load('model_traced.pt')
print('Loaded model output:', loaded(sample).shape)

import torch
import torch.nn as nn
import time

class DeepMLP(nn.Module):
    def __init__(self, dim: int = 512, depth: int = 8):
        super().__init__()
        layers = []
        for _ in range(depth):
            layers += [nn.Linear(dim, dim), nn.LayerNorm(dim), nn.GELU()]
        self.net = nn.Sequential(*layers)
        self.head = nn.Linear(dim, 10)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.head(self.net(x))

device = 'cuda' if torch.cuda.is_available() else 'cpu'
model_eager   = DeepMLP().to(device)
model_compiled = torch.compile(model_eager, mode='default')

x = torch.randn(256, 512, device=device)

# Warm up both (compiled model JIT-compiles on first call)
for _ in range(3):
    _ = model_eager(x)
    _ = model_compiled(x)

if device == 'cuda':
    torch.cuda.synchronize()

t0 = time.perf_counter()
for _ in range(100):
    _ = model_eager(x)
if device == 'cuda': torch.cuda.synchronize()
eager_t = time.perf_counter() - t0

t0 = time.perf_counter()
for _ in range(100):
    _ = model_compiled(x)
if device == 'cuda': torch.cuda.synchronize()
compiled_t = time.perf_counter() - t0

print(f'Eager:    {eager_t*10:.2f} ms/iter')
print(f'Compiled: {compiled_t*10:.2f} ms/iter')
print(f'Speedup:  {eager_t/compiled_t:.2f}x')

import jax
import jax.numpy as jnp
from jax import pmap, random
from jax.lax import pmean

n_devices = jax.device_count()
print(f'Available devices: {n_devices}')

# Replicate params across all devices
def replicate(x):
    return jnp.broadcast_to(x, (n_devices,) + x.shape)

key = random.PRNGKey(42)
params_rep = {
    'W': replicate(random.normal(key, (10, 5))),
    'b': replicate(jnp.zeros(5))
}

@pmap
def parallel_train_step(params, x_shard, y_shard):
    def loss_fn(p):
        logit = x_shard @ p['W'] + p['b']
        return jnp.mean((logit - y_shard) ** 2)
    grads = jax.grad(loss_fn)(params)
    # Average gradients across devices (allreduce)
    grads = jax.tree_util.tree_map(lambda g: pmean(g, axis_name='batch'), grads)
    return grads

print(f'pmap distributes batch axis over {n_devices} device(s)')
